drop table RSK_ISUP_INDICATOR;
CREATE TABLE
    RSK_ISUP_INDICATOR
    (
        IND_ID VARCHAR2(32) NOT NULL,
        IND_NAME VARCHAR2(200) NOT NULL,
        IND_TYPE VARCHAR2(50) NOT NULL,
        EXPR VARCHAR2(600) NOT NULL,
        SUP_TYPE VARCHAR2(50) NOT NULL,
        TIME_POINT VARCHAR2(50),
        SUP_FREQUENCY VARCHAR2(50),
        SUP_DIRECTION VARCHAR2(50),
        WARN_COND VARCHAR2(600),
        APPROVE_COND VARCHAR2(600),
        FOUL_COND VARCHAR2(2000),
        IS_ADJUST VARCHAR2(50),
        ADJUST NUMBER(10),
        IS_ENABLED VARCHAR2(50) NOT NULL,
        MEMO VARCHAR2(1000),
        CREATE_USER VARCHAR2(20) NOT NULL,
        CREATE_DEPT VARCHAR2(32),
        CREATE_TIME TIMESTAMP(6) NOT NULL,
        UPDATE_USER VARCHAR2(20) NOT NULL,
        UPDATE_TIME TIMESTAMP(6) NOT NULL,
        IS_EXCP_WHEN_DIV_ZERO VARCHAR2(50),
        COMPARE_DAYS NUMBER(10),
        INSTITUTION_CODE VARCHAR2(50),
        SUP_DISPLAY_CLASSIFY VARCHAR2(50),
        ASSET_THR_TYPE VARCHAR2(200),
        INVEST_PROPORTY VARCHAR2(200),
        IS_DISPLAY_ORIGINAL VARCHAR2(50),
        SUP_DOC VARCHAR2(200),
        IND_NUM CHAR(9) NOT NULL,
        CONSTRAINT PK_RSK_ISUP_INDICATOR PRIMARY KEY (IND_ID)
    );
COMMENT ON TABLE RSK_ISUP_INDICATOR
IS
    '风险监督指标';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.IND_ID
IS
    '监督指标编号';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.IND_NAME
IS
    '监督指标名称
';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.IND_TYPE
IS
    '指标类型';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.EXPR
IS
    '表达式';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.SUP_TYPE
IS
    '监督类型(SUPERVISION:监管,INTERNAL:内控)
';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.TIME_POINT
IS
    '监督时点(委托监控,交易监控,事后监控),多个用逗号分隔';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.SUP_FREQUENCY
IS
    '监督频率(日间、日终)
';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.SUP_DIRECTION
IS
    '监控方向';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.WARN_COND
IS
    '预警条件';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.APPROVE_COND
IS
    '审批条件';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.FOUL_COND
IS
    '违规条件';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.IS_ADJUST
IS
    '是否调整期';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.ADJUST
IS
    '调整期时间(天)';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.IS_ENABLED
IS
    '是否启用(是，否)，默认为是';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.MEMO
IS
    '备注';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.CREATE_USER
IS
    '创建人';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.CREATE_DEPT
IS
    '创建部门';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.CREATE_TIME
IS
    '创建时间';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.UPDATE_USER
IS
    '更新人';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.UPDATE_TIME
IS
    '更新时间';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.IS_EXCP_WHEN_DIV_ZERO
IS
    '除0是否异常';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.COMPARE_DAYS
IS
    '比较天数';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.SUP_DISPLAY_CLASSIFY
IS
    '指标分类维度';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.ASSET_THR_TYPE
IS
    '资产三级类型';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.INVEST_PROPORTY
IS
    '投资性质';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.IS_DISPLAY_ORIGINAL
IS
    '是否显示原值';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.SUP_DOC
IS
    '监管指标对应的监管文件说明';
COMMENT ON COLUMN RSK_ISUP_INDICATOR.IND_NUM
IS
    '指标编号：SUP-监管INT-内控CON-契约，中间的001代表监管指标数量，后001代表总的指标数量';
delete from RSK_ISUP_INDICATOR;
